import {industryRegistry,commodityRegistry,Registry} from './simulation-registry.js?v=babbc3d3950e';
import {compileManufacturingDefinition} from './industry-contract.js?v=babbc3d3950e';
// Overrides change economic definitions on full simulation restart; identities and artwork remain fixed.
export function resolveIndustryTuning(overrides=[]){if(!Array.isArray(overrides))throw TypeError('Industry tuning must be a list');const seen=new Set(),patches=new Map();for(const p of overrides){if(!p||!industryRegistry.has(p.id)||!industryRegistry.get(p.id).manufacturing||seen.has(p.id)||Object.keys(p).some(k=>!['id','inputs','outputs','base_build_cost','manufacturing'].includes(k)))throw TypeError('Invalid or duplicate industry tuning');seen.add(p.id);const d={...structuredClone(industryRegistry.get(p.id)),...structuredClone(p)};compileManufacturingDefinition(d,commodityRegistry.ids());patches.set(p.id,d);}return new Registry(industryRegistry.values().map(d=>patches.get(d.id)??d));}
